        }

        #region Implementation of ITablatureFileExporter

        public FileType FileType { get; private set; }

        public Version Version
        {
            get { return new Version("1.0"); }
        }

        public void Export(ITablatureFile file, string fileName)
        {
            using (var document = WordprocessingDocument.Create(fileName, WordprocessingDocumentType.Document))
            {
                var mainPart = document.AddMainDocumentPart();
                mainPart.Document = new Document();
                var body = mainPart.Document.AppendChild(new Body());
                var paragraph = body.AppendChild(new Paragraph());
                var run = paragraph.AppendChild(new Run());
                run.AppendChild(new Text(file.Contents));
                run.RunProperties =
                    new RunProperties(
                        new RunFonts() { Ascii = "Courier New", HighAnsi = "Courier New" },
                        new RunSize() { Val = 240 } // 9 points * 20
                    );
                document.Save();
            }
        }

        #endregion
    }
}

