    public class MvcApplication : System.Web.HttpApplication
    {
        protected void Application_Start()
        {
            AreaRegistration.RegisterAllAreas();
            FilterConfig.RegisterGlobalFilters(GlobalFilters.Filters);
            RouteConfig.RegisterRoutes(RouteTable.Routes);
            BundleConfig.RegisterBundles(BundleTable.Bundles);

            // Enable Cloud Foundry (CF) migrations on restart
            HostingEnvironment.RegisterVirtualPathProvider(new VirtualPathProvider());
        }
    }

    public class VirtualPathProvider : System.Web.Hosting.VirtualPathProvider
    {
        private static readonly List<VirtualPathProvider> _providers = new List<VirtualPathProvider>();

        public VirtualPathProvider()
        {
            lock (_providers)
            {
                if (!_providers.Contains(this))
                {
                    _providers.Add(this);
                }
            }
        }

        public override bool FileExists(string virtualPath)
        {
            foreach (var provider in _providers)
            {
                if (provider.FileExists(virtualPath))
                {
                    return true;
                }
            }
            return base.FileExists(virtualPath);
        }

        public override Stream OpenFile(string virtualPath, FileMode mode, FileAccess access, FileShare share, int bufferSize, FileOptions options)
        {
            foreach (var provider in _providers)
            {
                try
                {
                    var stream = provider.OpenFile(virtualPath, mode, access, share, bufferSize, options);
                    if (stream != null)
                    {
                        return stream;
                    }
                }
                catch { }
            }
            return base.OpenFile(virtualPath, mode, access, share, bufferSize, options);
        }
    }
}

